cards.name:
[[[
  if (!window.location.href.includes("cameras-detail")) {
    return "";
  }
  const playEntities = [
    "input_boolean.play_mezzanine_cam",
    "input_boolean.play_corridor_cam",
    "input_boolean.play_stair_cam"
  ];
  const stopEntities = [
    "input_boolean.play_front_cruiser_2",
    "input_boolean.play_garden_zoom",
    "input_boolean.play_garden_wide",
    "input_boolean.play_g5_garage"
  ];
  window.lastHass = hass;
  console.log("Invisible control card (cameras) evaluated!");

  // Turn ON subview G100 cameras immediately
  playEntities.forEach(ent => {
    if (hass.states[ent] && hass.states[ent].state === "off") {
      hass.callService("input_boolean", "turn_on", { entity_id: ent });
    }
  });

  // Turn OFF other background cameras
  stopEntities.forEach(ent => {
    if (hass.states[ent] && hass.states[ent].state === "on") {
      hass.callService("input_boolean", "turn_off", { entity_id: ent });
    }
  });
  return "";
]]]

